"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration
to /app/output.txt.
"""

import re

VALID_METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
VALID_PERMISSIONS = {"ALLOW", "DENY"}

VAR_PATTERN = re.compile(r"\{([A-Za-z0-9_-]+)\}")
ROLE_PATTERN = re.compile(r"^[A-Za-z0-9_-]+$")


def normalize_path(path):
    """Replace all {variable} patterns with {var} for matching purposes."""
    return VAR_PATTERN.sub("{var}", path)


def segment_count(path):
    """Count non-empty segments split on '/'."""
    return len([s for s in path.split("/") if s != ""])


def is_valid_path(path):
    """Path must be non-empty after stripping.

    Allowed characters: alphanumeric, '-', '_', '/', and {variable} patterns.
    Invalid variable patterns (with spaces, commas, colons, etc.) are treated
    as literal text -- which means the characters inside them must still be
    valid literal path characters.
    """
    if not path:
        return False
    # Remove valid {var} patterns, then check remaining characters.
    remainder = VAR_PATTERN.sub("", path)
    for ch in remainder:
        if not (ch.isalnum() or ch in "-_/" or ch in "{}"):
            return False
    return True


def parse_input(text):
    """Split the input into the three sections separated by empty lines."""
    lines = text.split("\n")
    # Handle trailing newline: split on empty lines into sections.
    sections = []
    current = []
    for line in lines:
        if line.strip() == "":
            if current or sections:
                sections.append(current)
                current = []
        else:
            current.append(line)
    if current or sections:
        sections.append(current)
    return sections


def parse_endpoints(lines):
    """Parse ENDPOINTS section with hard cutoff on malformed line.

    Returns list of dicts: path, method, role, permission (normalized).
    """
    endpoints = []
    for line in lines:
        parts = line.split()
        if len(parts) != 4:
            break
        path, method, role, permission = parts
        if not path:
            break
        method = method.upper()
        if method not in VALID_METHODS:
            break
        permission = permission.upper()
        if permission not in VALID_PERMISSIONS:
            break
        if not role or not ROLE_PATTERN.match(role):
            break
        endpoints.append({
            "path": path,
            "method": method,
            "role": role,
            "permission": permission,
        })
    return endpoints


def parse_base_exclude(lines):
    """Parse BASE/EXCLUDE section."""
    base = None
    exclude = set()
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "base" and len(parts) == 2:
            base = parts[1]
        elif parts[0] == "exclude":
            exclude.update(parts[1:])
    return base, exclude


def parse_plan(lines):
    """Parse PLAN section with hard cutoff on malformed line.

    Returns list of (path, method) tuples with normalized method.
    """
    plan = []
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            break
        path, method = parts
        if not path:
            break
        method = method.upper()
        if method not in VALID_METHODS:
            break
        plan.append((path, method))
    return plan


def main():
    with open("/app/input.txt", "r") as f:
        text = f.read()

    sections = parse_input(text)

    # Sections: 0 = ENDPOINTS, 1 = BASE/EXCLUDE, 2 = PLAN
    endpoint_lines = sections[0] if len(sections) > 0 else []
    base_exclude_lines = sections[1] if len(sections) > 1 else []
    plan_lines = sections[2] if len(sections) > 2 else []

    endpoints = parse_endpoints(endpoint_lines)
    base, exclude = parse_base_exclude(base_exclude_lines)
    plan = parse_plan(plan_lines)

    # Build per-path info keyed by normalized path.
    # Map normalized path -> list of endpoints (input order).
    from collections import OrderedDict
    norm_paths = OrderedDict()  # normalized path -> list of endpoint indices
    for idx, ep in enumerate(endpoints):
        np = normalize_path(ep["path"])
        norm_paths.setdefault(np, []).append(idx)

    # Determine eligibility (base prefix + role exclusion) per endpoint.
    def base_ok(path):
        if base is None:
            return True
        return path.startswith(base)

    eligible = []  # list of (endpoint, eligible_for_base)
    for idx, ep in enumerate(endpoints):
        eligible.append(base_ok(ep["path"]))

    # Path -> original path for output (first encountered variable names).
    # For each normalized path, the representative original path is the one
    # from the first endpoint encountered in input order.
    norm_to_original = {}
    for idx, ep in enumerate(endpoints):
        np = normalize_path(ep["path"])
        if np not in norm_to_original:
            norm_to_original[np] = ep["path"]

    # Determine which normalized paths are needed.
    # A path is needed if:
    #   - PLAN empty: all eligible paths (base-filtered) are included
    #     (excluded roles filtered out).
    #   - PLAN non-empty: each plan endpoint's path, plus any parent path
    #     (normalized prefix, not same, with at least one eligible endpoint
    #     after base/exclude filtering).
    plan_norms = set()
    for p, m in plan:
        plan_norms.add(normalize_path(p))

    needed_paths = set()

    # Eligible endpoints per normalized path (after base filter).
    # "eligible endpoint" = base_ok. Role exclusion handled separately.
    path_has_eligible = {}
    for np, idxs in norm_paths.items():
        path_has_eligible[np] = any(eligible[i] for i in idxs)

    def path_eligible_endpoints(np):
        """Endpoints for normalized path that pass base filter."""
        return [endpoints[i] for i in norm_paths.get(np, []) if eligible[i]]

    if not plan:
        # All eligible endpoints included; excluded roles filtered out.
        for np in norm_paths:
            if path_has_eligible[np]:
                needed_paths.add(np)
    else:
        # Each plan endpoint's own path (if it exists in ENDPOINTS).
        for np in plan_norms:
            if np in norm_paths:
                needed_paths.add(np)
        # Parent paths: for each plan endpoint, any path whose normalized
        # form is a proper prefix of the plan endpoint's normalized form,
        # and that has at least one eligible endpoint (base-filtered).
        for np in plan_norms:
            for parent_np in norm_paths:
                if parent_np == np:
                    continue
                if np.startswith(parent_np) and path_has_eligible[parent_np]:
                    needed_paths.add(parent_np)

    # Now collect endpoints to include, applying role exclusion with the
    # special-case inheritance exception.
    #
    # Special case: If a parent path has endpoints only for excluded roles,
    # but those endpoints are needed for inheritance resolution, include
    # them ONLY if they are the only endpoints for that parent path AND the
    # parent path is needed for inheritance.
    #
    # Interpretation: For a needed path, normally excluded-role endpoints
    # are dropped. Exception: if the path is a parent path (needed purely
    # for inheritance, i.e., not itself a plan endpoint or self-eligible
    # direct path) and ALL of its endpoints are for excluded roles, include
    # them.
    #
    # When PLAN is empty, excluded roles are always filtered out.

    def is_parent_only(np):
        """True if np is needed only as a parent (not a plan endpoint path)."""
        if not plan:
            return False
        return np in needed_paths and np not in plan_norms

    selected = []  # list of endpoint dicts
    for np in needed_paths:
        eps = path_has_eligible and path_eligible_endpoints(np)
        # Determine which roles appear on this path (base-eligible endpoints).
        non_excluded = [e for e in eps if e["role"] not in exclude]
        excluded_only = [e for e in eps if e["role"] in exclude]
        if non_excluded:
            selected.extend(non_excluded)
        else:
            # All endpoints on this path are for excluded roles.
            # Include only under the inheritance special case.
            if plan and is_parent_only(np) and excluded_only:
                selected.extend(excluded_only)

    # Deduplicate by (original path, method, role), keeping first in input
    # order. Note: uniqueness is by original path variable names.
    seen = set()
    unique = []
    # Order selected by input order for deterministic first-encountered.
    order = {id(e): i for i, e in enumerate(endpoints)}
    selected_sorted = sorted(selected, key=lambda e: order[id(e)])
    for e in selected_sorted:
        key = (e["path"], e["method"], e["role"])
        if key in seen:
            continue
        seen.add(key)
        unique.append(e)

    # Ordering:
    # 1. Path length in segments (longer first)
    # 2. Method alphabetical
    # 3. Role lexicographic (case-sensitive)
    # 4. Permission (ALLOW before DENY)
    def sort_key(e):
        return (
            -segment_count(e["path"]),
            e["method"],
            e["role"],
            0 if e["permission"] == "ALLOW" else 1,
        )

    unique.sort(key=sort_key)

    if unique:
        out_lines = ["{} {} {} {}".format(e["path"], e["method"], e["role"],
                                          e["permission"]) for e in unique]
        output = "\n".join(out_lines) + "\n"
    else:
        output = "\n"

    with open("/app/output.txt", "w") as f:
        f.write(output)


if __name__ == "__main__":
    main()
"}

